// ─── Admin Panel ──────────────────────────────────────────────────────────────
function AdminPanel({ currentUser, profiles, setProfiles, onLogout }) {
  const [plates, setPlates] = useState([]);
  const [loading, setLoading] = useState(true);
  const [tab, setTab] = useState("monitor");
  const [adminSearch, setAdminSearch] = useState("");
  const [filterStatus, setFilterStatus] = useState("All");
  const [filterAddress, setFilterAddress] = useState("All");
  const [currentPage, setCurrentPage] = useState(1);
  const PAGE_SIZE = 50;

  // Unique sorted barangay list
  const addressOptions = ["All", ...Array.from(new Set(plates.map(p => p.applicantAddress).filter(Boolean))).sort()];

  const searchTerm = adminSearch.trim();
  const hasActiveFilter = searchTerm !== "" || filterStatus !== "All" || filterAddress !== "All";

  const filteredPlates = useMemo(() => {
    if (!hasActiveFilter) return [];
    return plates.filter(p => {
      // Search match
      let matchSearch = true;
      if (searchTerm) {
        const isExactPlate = /^[A-Z]{3}[0-9]{3}$/.test(searchTerm);
        if (isExactPlate) {
          matchSearch = p.plateNumber === searchTerm;
        } else {
          matchSearch = p.plateNumber.startsWith(searchTerm) || p.applicantName.toUpperCase().includes(searchTerm);
        }
      }
      const matchStatus = filterStatus === "All" || p.status === filterStatus;
      const matchAddress = filterAddress === "All" || p.applicantAddress === filterAddress;
      return matchSearch && matchStatus && matchAddress;
    });
  }, [plates, searchTerm, filterStatus, filterAddress, hasActiveFilter]);

  const totalPages = Math.max(1, Math.ceil(filteredPlates.length / PAGE_SIZE));
  const pagedPlates = useMemo(() => {
    if (!hasActiveFilter) return [];
    return filteredPlates.slice((currentPage - 1) * PAGE_SIZE, currentPage * PAGE_SIZE);
  }, [filteredPlates, currentPage, hasActiveFilter]);
  const [csvText, setCsvText] = useState("");
  const [parseResult, setParseResult] = useState(null);
  const [importDone, setImportDone] = useState(false);
  const [editPlate, setEditPlate] = useState(null);
  const [claimPlate, setClaimPlate] = useState(null);
  const [viewClaimPlate, setViewClaimPlate] = useState(null);
  const [showNewPlate, setShowNewPlate] = useState(false);
  const [searchDetail, setSearchDetail] = useState(null);
  const fileRef = useRef();

  const handleAdminSearch = () => {
    const q = adminSearch.trim();
    if (!q) return;
    const isExact = /^[A-Z]{3}[0-9]{3}$/.test(q);
    if (isExact) {
      const found = plates.find(p => p.plateNumber === q);
      setSearchDetail(found || "not_found");
    } else {
      setSearchDetail(null);
    }
  };

  const loadingRef = useRef(false);

  const loadPlates = useCallback(async () => {
    // Prevent concurrent loads which cause duplicate rows
    if (loadingRef.current) return;
    loadingRef.current = true;
    setLoading(true);
    // Paginate to bypass Supabase 1000-row default limit
    let all = [], from = 0, pageSize = 1000, done = false;
    while (!done) {
      const { data, error } = await supabase.from("plates").select("*").order("created_at", { ascending: false }).range(from, from + pageSize - 1);
      if (error || !data || data.length === 0) { done = true; }
      else { all = [...all, ...data]; from += pageSize; if (data.length < pageSize) done = true; }
    }
    // Deduplicate by plate_number (keep latest by created_at) — handles DB duplicates
    const byPlate = new Map();
    all.forEach(r => {
      const existing = byPlate.get(r.plate_number);
      if (!existing || new Date(r.created_at) > new Date(existing.created_at)) {
        byPlate.set(r.plate_number, r);
      }
    });
    setPlates(Array.from(byPlate.values()).map(dbToPlate));
    setLoading(false);
    loadingRef.current = false;
  }, []);

  useEffect(() => { loadPlates(); }, [loadPlates]);

  // Real-time updates — debounced to avoid multiple rapid reloads
  useEffect(() => {
    let debounceTimer = null;
    const channel = supabase.channel("plates-admin").on("postgres_changes", { event: "*", schema: "public", table: "plates" }, () => {
      clearTimeout(debounceTimer);
      debounceTimer = setTimeout(() => loadPlates(), 800);
    }).subscribe();
    return () => { clearTimeout(debounceTimer); supabase.removeChannel(channel); };
  }, [loadPlates]);

  const handleFile = (e) => { const f=e.target.files[0]; if(!f) return; const r=new FileReader(); r.onload=ev=>{const t=ev.target.result;setCsvText(t);setParseResult(parseCSV(t));setImportDone(false);}; r.readAsText(f); };
  const handlePaste = (e) => { const t=e.target.value; setCsvText(t); setParseResult(t.trim()?parseCSV(t):null); setImportDone(false); };
  const handleImport = async () => {
    if (!parseResult?.rows?.length) return;
    // Deduplicate — keep last occurrence of each plate number
    const seen = new Map();
    parseResult.rows.forEach(r => seen.set(r.plateNumber, r));
    const unique = Array.from(seen.values());
    const dupeCount = parseResult.rows.length - unique.length;
    const inserts = unique.map(r => plateToDb(r));
    const { error } = await supabase.from("plates").upsert(inserts, { onConflict: "plate_number" });
    if (error) { alert("Import error: " + error.message); return; }
    setImportDone(true);
    setParseResult(null);
    setCsvText("");
    setTab("table");
    await loadPlates();
    if (dupeCount > 0) alert(`Import complete. ${dupeCount} duplicate plate number(s) in the CSV were merged (last row kept).`);
  };
  const handleDeletePlate = async (id) => {
    if (!window.confirm("Delete this plate record?")) return;
    await supabase.from("plates").delete().eq("id", id);
    setPlates(prev => prev.filter(p => p.id !== id));
  };
  const handleSavePlate = (updated) => {
    setPlates(prev => {
      const idx = prev.findIndex(p => p.id === updated.id);
      if (idx >= 0) { const n = [...prev]; n[idx] = updated; return n; }
      // New plate — add only if not already in list
      if (prev.some(p => p.plateNumber === updated.plateNumber)) return prev.map(p => p.plateNumber === updated.plateNumber ? updated : p);
      return [updated, ...prev];
    });
    setEditPlate(null);
    setShowNewPlate(false);
  };
  const handleSaveClaim = (updated) => {
    setPlates(prev => prev.map(p => p.id===updated.id?updated:p));
    setClaimPlate(null);
    // Refresh detail pane if this plate is currently shown
    setSearchDetail(prev => prev && prev !== "not_found" && prev.id===updated.id ? updated : prev);
  };
  const downloadSample = () => { const b=new Blob([SAMPLE_CSV],{type:"text/csv"}); const u=URL.createObjectURL(b); const a=document.createElement("a"); a.href=u; a.download="sample_plates.csv"; a.click(); URL.revokeObjectURL(u); };

  const tabs = [
    { id:"monitor", label:"Dashboard", icon:LayoutDashboard },
    { id:"table", label:"Plates", icon:Table, count:plates.length },
    { id:"import", label:"Import CSV", icon:Upload },
    ...(currentUser.role==="superadmin"?[{id:"accounts",label:"Accounts",icon:Users,count:profiles.length}]:[]),
  ];

  return (
    <div className="min-h-screen bg-gray-50">
      {editPlate && <EditPlateModal plate={editPlate} onClose={()=>setEditPlate(null)} onSave={handleSavePlate}/>}
      {showNewPlate && <EditPlateModal plate={{}} onClose={()=>setShowNewPlate(false)} onSave={handleSavePlate}/>}
      {claimPlate && <ClaimModal plate={claimPlate} currentUser={currentUser} onClose={()=>setClaimPlate(null)} onSave={handleSaveClaim}/>}
      {viewClaimPlate && <ClaimViewModal plate={viewClaimPlate} onClose={()=>setViewClaimPlate(null)}/>}

      <LTOHeader subtitle={`${currentUser.full_name} — ${currentUser.role==="superadmin"?"Super Admin":"Admin Officer"}`}
        rightSlot={<button onClick={onLogout} className="flex items-center gap-2 text-xs bg-blue-800 hover:bg-blue-700 px-3 py-2 rounded-lg transition-colors"><LogOut size={14}/> Logout</button>}/>

      <div className="max-w-5xl mx-auto px-4 py-6 space-y-5">
        <div className="flex flex-wrap gap-2 items-center">
          {tabs.map(t=>(<button key={t.id} onClick={()=>setTab(t.id)} className={`px-4 py-2 rounded-xl text-sm font-semibold transition-colors flex items-center gap-2 ${tab===t.id?"bg-blue-700 text-white shadow":"bg-white text-gray-600 border border-gray-200 hover:bg-gray-50"}`}><t.icon size={15}/>{t.label}{t.count!==undefined&&<span className={`text-xs px-1.5 py-0.5 rounded-full ${tab===t.id?"bg-white bg-opacity-20 text-white":"bg-gray-100 text-gray-500"}`}>{t.count}</span>}</button>))}
          <button onClick={loadPlates} className="ml-auto p-2 text-gray-400 hover:text-blue-700 hover:bg-blue-50 rounded-lg transition-colors" title="Refresh"><RefreshCw size={15}/></button>
        </div>

        {importDone && <div className="bg-green-50 border border-green-200 rounded-xl px-4 py-3 flex items-center gap-3 text-green-800 text-sm font-semibold"><CheckCircle size={16} className="text-green-500"/> CSV imported successfully.</div>}

        {tab==="monitor" && (() => {
          const totalPlates   = plates.length;
          const claimed       = plates.filter(p => p.status === "Claimed").length;
          const available     = plates.filter(p => p.status === "Available for Claiming").length;
          const received      = plates.filter(p => p.status === "Received").length;
          const remaining     = available + received;
          const claimedPct    = totalPlates ? Math.round((claimed / totalPlates) * 100) : 0;
          const availablePct  = totalPlates ? Math.round((available / totalPlates) * 100) : 0;
          const receivedPct   = totalPlates ? Math.round((received / totalPlates) * 100) : 0;
          const recentClaimed = [...plates]
            .filter(p => p.status === "Claimed" && p.lastUpdated)
            .sort((a,b) => new Date(b.lastUpdated) - new Date(a.lastUpdated))
            .slice(0, 10);
          return (
            <div className="space-y-5">
              <div className="flex items-center justify-between">
                <div>
                  <h2 className="text-xl font-black text-gray-800">Monitoring Dashboard</h2>
                  <p className="text-xs text-gray-400 mt-0.5">Real-time plate release monitoring — LTO Binangonan Extension Office</p>
                </div>
                <button onClick={loadPlates} className="flex items-center gap-1.5 text-xs text-gray-500 hover:text-blue-700 px-3 py-2 rounded-lg hover:bg-blue-50 border border-gray-200 transition-colors"><RefreshCw size={13}/> Refresh</button>
              </div>
              <div className="grid grid-cols-1 gap-4 sm:grid-cols-3">
                <div className="bg-white rounded-2xl border border-gray-100 shadow-sm p-5 flex flex-col gap-3">
                  <div className="flex items-center justify-between">
                    <div className="w-11 h-11 rounded-xl bg-green-100 flex items-center justify-center"><CheckCircle size={22} className="text-green-600"/></div>
                    <span className="text-xs font-bold text-green-600 bg-green-50 border border-green-200 px-2.5 py-1 rounded-full">{claimedPct}%</span>
                  </div>
                  <div>
                    <p className="text-xs font-bold text-gray-400 uppercase tracking-widest">Released Plates</p>
                    <p className="text-5xl font-black text-gray-900 mt-1 tabular-nums">{claimed.toLocaleString()}</p>
                    <p className="text-xs text-gray-400 mt-1.5">plates successfully claimed</p>
                  </div>
                  <div className="w-full bg-gray-100 rounded-full h-2.5">
                    <div className="bg-green-500 h-2.5 rounded-full" style={{width: claimedPct + "%"}}/>
                  </div>
                </div>
                <div className="bg-white rounded-2xl border border-gray-100 shadow-sm p-5 flex flex-col gap-3">
                  <div className="flex items-center justify-between">
                    <div className="w-11 h-11 rounded-xl bg-blue-100 flex items-center justify-center"><Package size={22} className="text-blue-600"/></div>
                    <span className="text-xs font-bold text-blue-600 bg-blue-50 border border-blue-200 px-2.5 py-1 rounded-full">{availablePct}%</span>
                  </div>
                  <div>
                    <p className="text-xs font-bold text-gray-400 uppercase tracking-widest">Available for Claiming</p>
                    <p className="text-5xl font-black text-gray-900 mt-1 tabular-nums">{available.toLocaleString()}</p>
                    <p className="text-xs text-gray-400 mt-1.5">plates ready to be picked up</p>
                  </div>
                  <div className="w-full bg-gray-100 rounded-full h-2.5">
                    <div className="bg-blue-500 h-2.5 rounded-full" style={{width: availablePct + "%"}}/>
                  </div>
                </div>
                <div className="bg-white rounded-2xl border border-gray-100 shadow-sm p-5 flex flex-col gap-3">
                  <div className="flex items-center justify-between">
                    <div className="w-11 h-11 rounded-xl bg-amber-100 flex items-center justify-center"><Archive size={22} className="text-amber-600"/></div>
                    <span className="text-xs font-bold text-amber-600 bg-amber-50 border border-amber-200 px-2.5 py-1 rounded-full">{100-claimedPct}%</span>
                  </div>
                  <div>
                    <p className="text-xs font-bold text-gray-400 uppercase tracking-widest">Total Remaining</p>
                    <p className="text-5xl font-black text-gray-900 mt-1 tabular-nums">{remaining.toLocaleString()}</p>
                    <p className="text-xs text-gray-400 mt-1.5">plates not yet claimed</p>
                  </div>
                  <div className="w-full bg-gray-100 rounded-full h-2.5">
                    <div className="bg-amber-400 h-2.5 rounded-full" style={{width: (100 - claimedPct) + "%"}}/>
                  </div>
                </div>
              </div>
              <div className="bg-white rounded-2xl border border-gray-100 shadow-sm p-5">
                <h3 className="text-sm font-bold text-gray-700 mb-4 flex items-center gap-2"><ClipboardList size={15} className="text-blue-700"/> Overall Summary</h3>
                <div className="grid grid-cols-2 gap-4 sm:grid-cols-4 mb-5">
                  <div className="text-center p-3 bg-gray-50 rounded-xl">
                    <p className="text-3xl font-black text-gray-900 tabular-nums">{totalPlates.toLocaleString()}</p>
                    <p className="text-xs text-gray-400 mt-1 font-semibold">Total Plates</p>
                  </div>
                  <div className="text-center p-3 bg-green-50 rounded-xl">
                    <p className="text-3xl font-black text-green-700 tabular-nums">{claimed.toLocaleString()}</p>
                    <p className="text-xs text-green-600 mt-1 font-semibold">Claimed</p>
                  </div>
                  <div className="text-center p-3 bg-blue-50 rounded-xl">
                    <p className="text-3xl font-black text-blue-700 tabular-nums">{available.toLocaleString()}</p>
                    <p className="text-xs text-blue-600 mt-1 font-semibold">Available</p>
                  </div>
                  <div className="text-center p-3 bg-amber-50 rounded-xl">
                    <p className="text-3xl font-black text-amber-700 tabular-nums">{received.toLocaleString()}</p>
                    <p className="text-xs text-amber-600 mt-1 font-semibold">Received</p>
                  </div>
                </div>
                <div className="w-full flex rounded-full overflow-hidden h-5 shadow-inner bg-gray-100">
                  {claimedPct > 0 && <div className="bg-green-500 flex items-center justify-center text-white text-xs font-bold" style={{width: claimedPct + "%"}}>{claimedPct >= 6 ? claimedPct+"%" : ""}</div>}
                  {availablePct > 0 && <div className="bg-blue-500 flex items-center justify-center text-white text-xs font-bold" style={{width: availablePct + "%"}}>{availablePct >= 6 ? availablePct+"%" : ""}</div>}
                  {receivedPct > 0 && <div className="bg-amber-400 flex items-center justify-center text-white text-xs font-bold" style={{width: receivedPct + "%"}}>{receivedPct >= 6 ? receivedPct+"%" : ""}</div>}
                </div>
                <div className="flex gap-5 mt-3 justify-center flex-wrap">
                  <span className="flex items-center gap-1.5 text-xs text-gray-500 font-medium"><span className="w-3 h-3 rounded-full bg-green-500 inline-block"/> Claimed</span>
                  <span className="flex items-center gap-1.5 text-xs text-gray-500 font-medium"><span className="w-3 h-3 rounded-full bg-blue-500 inline-block"/> Available for Claiming</span>
                  <span className="flex items-center gap-1.5 text-xs text-gray-500 font-medium"><span className="w-3 h-3 rounded-full bg-amber-400 inline-block"/> Received (pending release)</span>
                </div>
              </div>
              {recentClaimed.length > 0 && (
                <div className="bg-white rounded-2xl border border-gray-100 shadow-sm overflow-hidden">
                  <div className="px-5 py-4 border-b border-gray-100 flex items-center gap-2">
                    <TrendingUp size={15} className="text-green-600"/>
                    <h3 className="text-sm font-bold text-gray-700">Recently Claimed</h3>
                    <span className="text-xs text-gray-400 ml-1">(latest 10)</span>
                  </div>
                  <div className="overflow-x-auto">
                    <table className="w-full text-sm">
                      <thead><tr className="bg-gray-50 border-b border-gray-100">
                        {["Plate No.","Applicant","Box No.","Received By","Claimed On"].map(h=><th key={h} className="px-4 py-3 text-left text-xs font-bold text-gray-500 uppercase tracking-wide whitespace-nowrap">{h}</th>)}
                      </tr></thead>
                      <tbody>
                        {recentClaimed.map(p=>(
                          <tr key={p.id} className="border-b border-gray-50 hover:bg-gray-50 transition-colors">
                            <td className="px-4 py-3 font-mono font-bold text-gray-800">{p.plateNumber}</td>
                            <td className="px-4 py-3 text-gray-700 text-xs">{p.applicantName||"—"}</td>
                            <td className="px-4 py-3 text-gray-500 text-xs font-mono">{p.boxNumber||"—"}</td>
                            <td className="px-4 py-3 text-gray-600 text-xs">{p.claimData?.receivedBy||"—"}</td>
                            <td className="px-4 py-3 text-gray-400 text-xs whitespace-nowrap">{p.claimData?.claimedAt||p.lastUpdated||"—"}</td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                </div>
              )}
            </div>
          );
        })()}

        {searchDetail && (
          <div className="fixed inset-0 bg-black bg-opacity-50 z-50 flex items-center justify-center p-4" onClick={e=>{ if(e.target===e.currentTarget) setSearchDetail(null); }}>
          <div className="bg-white rounded-2xl shadow-2xl w-full max-w-md overflow-hidden">
            <div className="bg-blue-900 rounded-t-2xl px-5 py-4 flex items-center justify-between">
              <div>
                <p className="text-blue-200 text-xs font-semibold uppercase tracking-widest">Search Result</p>
                <h2 className="text-white font-bold text-lg font-mono">{searchDetail==="not_found" ? "Not Found" : searchDetail.plateNumber}</h2>
              </div>
              <button onClick={()=>setSearchDetail(null)} className="text-blue-300 hover:text-white"><X size={20}/></button>
            </div>
            {searchDetail==="not_found" ? (
              <div className="p-10 text-center">
                <XCircle size={48} className="text-red-400 mx-auto mb-4"/>
                <p className="text-gray-800 font-bold text-lg">Plate Not Found</p>
                <p className="text-gray-400 text-sm mt-1 font-mono">"{adminSearch}"</p>
                <p className="text-gray-400 text-xs mt-2">This plate number is not in the database.</p>
                <button onClick={()=>setSearchDetail(null)} className="mt-5 px-5 py-2 bg-gray-100 hover:bg-gray-200 rounded-lg text-sm font-semibold text-gray-600">Close</button>
              </div>
            ) : (
              <div className="p-5 space-y-4">
                {/* Status banner */}
                <div className={`rounded-xl px-4 py-3 flex items-center gap-3 ${
                  searchDetail.status==="Available for Claiming" ? "bg-green-50 border border-green-200" :
                  searchDetail.status==="Claimed" ? "bg-gray-50 border border-gray-200" : "bg-blue-50 border border-blue-200"
                }`}>
                  <StatusBadge status={searchDetail.status}/>
                  <span className="text-sm font-semibold text-gray-700">{searchDetail.status}</span>
                </div>
                {/* Details grid */}
                <div className="grid grid-cols-2 gap-3">
                  {searchDetail.boxNumber && (
                    <div className="bg-amber-50 border border-amber-200 rounded-xl p-3 col-span-2">
                      <p className="text-xs text-amber-600 font-bold uppercase mb-1">📦 Box Number</p>
                      <p className="text-lg font-bold text-amber-800">{searchDetail.boxNumber}</p>
                    </div>
                  )}
                  <div className="bg-gray-50 rounded-xl p-3">
                    <p className="text-xs text-gray-500 font-semibold uppercase mb-1">Plate Number</p>
                    <p className="text-sm font-bold text-gray-800 font-mono">{searchDetail.plateNumber}</p>
                  </div>
                  <div className="bg-gray-50 rounded-xl p-3">
                    <p className="text-xs text-gray-500 font-semibold uppercase mb-1">Last Updated</p>
                    <p className="text-sm font-bold text-gray-800">{searchDetail.lastUpdated||"—"}</p>
                  </div>
                  <div className="bg-gray-50 rounded-xl p-3 col-span-2">
                    <p className="text-xs text-gray-500 font-semibold uppercase mb-1">Applicant Name</p>
                    <p className="text-sm font-bold text-gray-800">{searchDetail.applicantName||"—"}</p>
                  </div>
                  <div className="bg-gray-50 rounded-xl p-3 col-span-2">
                    <p className="text-xs text-gray-500 font-semibold uppercase mb-1">Address / Barangay</p>
                    <p className="text-sm text-gray-700">{searchDetail.applicantAddress||"—"}</p>
                  </div>
                  {searchDetail.applicantEmail && (
                    <div className="bg-gray-50 rounded-xl p-3 col-span-2">
                      <p className="text-xs text-gray-500 font-semibold uppercase mb-1">Email</p>
                      <p className="text-sm text-gray-700">{searchDetail.applicantEmail}</p>
                    </div>
                  )}
                  <div className="bg-gray-50 rounded-xl p-3">
                    <p className="text-xs text-gray-500 font-semibold uppercase mb-1">Classification</p>
                    <p className="text-sm text-gray-700">{searchDetail.classification||"—"}</p>
                  </div>
                  <div className="bg-gray-50 rounded-xl p-3">
                    <p className="text-xs text-gray-500 font-semibold uppercase mb-1">Assigned Office</p>
                    <p className="text-sm text-gray-700">{searchDetail.assignedOffice||"—"}</p>
                  </div>
                  {searchDetail.status==="Claimed" && searchDetail.claimData && (
                    <>
                      <div className="bg-green-50 border border-green-200 rounded-xl p-3 col-span-2">
                        <p className="text-xs text-green-600 font-bold uppercase mb-2">Claim Information</p>
                        <p className="text-xs text-gray-700"><span className="font-semibold">Received By:</span> {searchDetail.claimData.receivedBy}</p>
                        <p className="text-xs text-gray-700 mt-1"><span className="font-semibold">Claimed On:</span> {searchDetail.claimData.claimedAt}</p>
                        <p className="text-xs text-gray-700 mt-1"><span className="font-semibold">Released By:</span> {searchDetail.claimData.releasedBy}</p>
                      </div>
                      {searchDetail.claimData.signature && (
                        <div className="bg-gray-50 rounded-xl p-3 col-span-2">
                          <p className="text-xs text-gray-500 font-semibold uppercase mb-2">Signature</p>
                          <img src={searchDetail.claimData.signature} alt="Signature" className="max-h-20 border border-gray-200 rounded-lg bg-white p-1"/>
                        </div>
                      )}
                      {searchDetail.claimData.photo && (
                        <div className="bg-gray-50 rounded-xl p-3 col-span-2">
                          <p className="text-xs text-gray-500 font-semibold uppercase mb-2">Proof of Identity</p>
                          <img src={searchDetail.claimData.photo} alt="ID" className="max-h-40 rounded-lg border border-gray-200"/>
                        </div>
                      )}
                    </>
                  )}
                </div>
                {/* Action buttons */}
                <div className="flex gap-2 pt-1">
                  <button onClick={()=>setEditPlate(searchDetail)} className="flex-1 py-2.5 border border-blue-200 text-blue-700 text-xs font-semibold rounded-xl hover:bg-blue-50 flex items-center justify-center gap-1.5"><Edit3 size={13}/> Edit</button>
                  {searchDetail.status==="Available for Claiming" && (
                    <button onClick={()=>setClaimPlate(searchDetail)} className="flex-1 py-2.5 bg-green-600 text-white text-xs font-semibold rounded-xl hover:bg-green-700 flex items-center justify-center gap-1.5"><CheckSquare size={13}/> Mark as Claimed</button>
                  )}
                  {searchDetail.status==="Claimed" && searchDetail.claimData && (
                    <button onClick={()=>setViewClaimPlate(searchDetail)} className="flex-1 py-2.5 border border-gray-200 text-gray-600 text-xs font-semibold rounded-xl hover:bg-gray-50 flex items-center justify-center gap-1.5"><FileText size={13}/> View Full Claim</button>
                  )}
                  <button onClick={()=>handleDeletePlate(searchDetail.id)} className="px-4 py-2.5 border border-red-200 text-red-500 text-xs font-semibold rounded-xl hover:bg-red-50 flex items-center justify-center gap-1.5"><Trash2 size={13}/></button>
                </div>
              </div>
            )}
          </div>
          </div>
        )}

        {tab==="table" && (
          <div className="bg-white rounded-2xl border border-gray-100 shadow-sm overflow-hidden">
            <div className="px-5 py-4 border-b border-gray-100 space-y-3">
              <div className="flex items-center justify-between flex-wrap gap-3">
                <h2 className="font-bold text-gray-800">Plate Records <span className="text-xs font-normal text-gray-400 ml-1">{hasActiveFilter ? `${filteredPlates.length} result${filteredPlates.length!==1?"s":""} of ${plates.length} plates` : `${plates.length} total plates — use search or filters`}</span></h2>
                <button onClick={()=>setShowNewPlate(true)} className="flex items-center gap-2 text-xs bg-blue-700 text-white px-3 py-2 rounded-lg hover:bg-blue-800 font-semibold"><PlusCircle size={14}/> Add Plate</button>
              </div>
              <div className="flex flex-wrap gap-2 items-center">
                {/* Search */}
                <div className="flex items-center gap-2">
                  <div className="relative">
                    <Search size={14} className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400"/>
                    <input
                      value={adminSearch}
                      onChange={e=>{
                        const v = e.target.value.replace(/\s+/g,"").toUpperCase();
                        setAdminSearch(v);
                        setCurrentPage(1);
                        setSearchDetail(null);
                      }}
                      onKeyDown={e=>{ if(e.key==="Enter") handleAdminSearch(); }}
                      placeholder="Type plate no. e.g. UKL601"
                      className="pl-8 pr-3 py-2.5 text-sm border border-gray-200 rounded-lg focus:outline-none focus:border-blue-500 w-60 font-mono tracking-widest"
                    />
                  </div>
                  <button onClick={handleAdminSearch} className="flex items-center gap-2 px-5 py-2.5 bg-blue-700 text-white text-sm font-bold rounded-lg hover:bg-blue-800 shadow-sm"><Search size={15}/> Search</button>
                </div>
                {/* Status filter */}
                <select value={filterStatus} onChange={e=>{setFilterStatus(e.target.value);setCurrentPage(1);}} className="text-xs border border-gray-200 rounded-lg px-3 py-2 focus:outline-none focus:border-blue-500 bg-white text-gray-700">
                  {["All","Received","Available for Claiming","Claimed"].map(s=><option key={s} value={s}>{s==="All"?"All Statuses":s}</option>)}
                </select>
                {/* Barangay filter */}
                <select value={filterAddress} onChange={e=>{setFilterAddress(e.target.value);setCurrentPage(1);}} className="text-xs border border-gray-200 rounded-lg px-3 py-2 focus:outline-none focus:border-blue-500 bg-white text-gray-700 max-w-[180px]">
                  {addressOptions.map(a=><option key={a} value={a}>{a==="All"?"All Barangays":a}</option>)}
                </select>
                {/* Clear filters */}
                {(adminSearch||filterStatus!=="All"||filterAddress!=="All") && (
                  <button onClick={()=>{setAdminSearch("");setFilterStatus("All");setFilterAddress("All");setCurrentPage(1);}} className="text-xs text-red-500 hover:text-red-700 px-2 py-2 rounded-lg hover:bg-red-50 flex items-center gap-1"><X size={12}/> Clear</button>
                )}
              </div>
            </div>
            {loading ? (
              <div className="p-12 flex justify-center"><Loader size={24} className="animate-spin text-blue-700"/></div>
            ) : (
              <div className="overflow-x-auto">
                <table className="w-full text-sm">
                  <thead><tr className="bg-gray-50 border-b border-gray-100">{["Box No.","Plate No.","Applicant","Address","Email","Status","Last Updated","Actions"].map(h=><th key={h} className="px-4 py-3 text-left text-xs font-bold text-gray-500 uppercase tracking-wide whitespace-nowrap">{h}</th>)}</tr></thead>
                  <tbody>
                    {!hasActiveFilter && <tr><td colSpan={8} className="px-4 py-16 text-center"><div className="flex flex-col items-center gap-3 text-gray-400"><Search size={32} className="opacity-30"/><p className="text-sm font-medium">Search a plate number or name, or use the filters above</p><p className="text-xs opacity-70">e.g. type "XNG460" to find that specific plate</p></div></td></tr>}
                    {hasActiveFilter && pagedPlates.length===0 && <tr><td colSpan={8} className="px-4 py-8 text-center text-gray-400 text-sm">No plates match your search or filters.</td></tr>}
                    {hasActiveFilter && pagedPlates.map(p=>(
                      <tr key={p.id} className="border-b border-gray-50 hover:bg-gray-50 transition-colors">
                        <td className="px-4 py-3 text-gray-500 text-xs whitespace-nowrap">{p.boxNumber||"—"}</td>
                        <td className="px-4 py-3 font-mono font-bold text-gray-800 whitespace-nowrap">{p.plateNumber}</td>
                        <td className="px-4 py-3 text-gray-700 whitespace-nowrap">{p.applicantName}</td>
                        <td className="px-4 py-3 text-gray-600 text-xs max-w-[180px] truncate" title={p.applicantAddress}>{p.applicantAddress||"—"}</td>
                        <td className="px-4 py-3 text-gray-500 text-xs whitespace-nowrap">{p.applicantEmail||"—"}</td>
                        <td className="px-4 py-3 whitespace-nowrap"><StatusBadge status={p.status}/></td>
                        <td className="px-4 py-3 text-gray-500 text-xs whitespace-nowrap">{p.lastUpdated}</td>
                        <td className="px-4 py-3">
                          <div className="flex items-center gap-1">
                            <button onClick={()=>setEditPlate(p)} title="Edit" className="text-blue-500 hover:text-blue-700 p-1 rounded hover:bg-blue-50"><Edit3 size={14}/></button>
                            {p.status==="Available for Claiming" && <button onClick={()=>setClaimPlate(p)} title="Record Claim" className="text-green-600 hover:text-green-800 p-1 rounded hover:bg-green-50"><CheckSquare size={14}/></button>}
                            {p.status==="Claimed" && p.claimData && <button onClick={()=>setViewClaimPlate(p)} title="View Claim Details" className="text-gray-500 hover:text-gray-700 p-1 rounded hover:bg-gray-50"><FileText size={14}/></button>}
                            <button onClick={()=>handleDeletePlate(p.id)} title="Delete" className="text-red-500 hover:text-red-700 p-1 rounded hover:bg-red-50"><Trash2 size={14}/></button>
                          </div>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            )}
            {/* Pagination */}
            {!loading && filteredPlates.length > PAGE_SIZE && (
              <div className="px-5 py-4 border-t border-gray-100 flex items-center justify-between flex-wrap gap-3">
                <span className="text-xs text-gray-500">
                  Showing {((currentPage-1)*PAGE_SIZE)+1}–{Math.min(currentPage*PAGE_SIZE, filteredPlates.length)} of {filteredPlates.length} plates
                </span>
                <div className="flex items-center gap-1">
                  <button onClick={()=>setCurrentPage(1)} disabled={currentPage===1} className="px-2 py-1.5 text-xs rounded-lg border border-gray-200 disabled:opacity-40 hover:bg-gray-50 disabled:cursor-not-allowed">«</button>
                  <button onClick={()=>setCurrentPage(p=>Math.max(1,p-1))} disabled={currentPage===1} className="px-3 py-1.5 text-xs rounded-lg border border-gray-200 disabled:opacity-40 hover:bg-gray-50 disabled:cursor-not-allowed">‹ Prev</button>
                  {Array.from({length: Math.min(5, totalPages)}, (_,i) => {
                    let page;
                    if (totalPages <= 5) page = i+1;
                    else if (currentPage <= 3) page = i+1;
                    else if (currentPage >= totalPages-2) page = totalPages-4+i;
                    else page = currentPage-2+i;
                    return (
                      <button key={page} onClick={()=>setCurrentPage(page)} className={`px-3 py-1.5 text-xs rounded-lg border ${currentPage===page?"bg-blue-700 text-white border-blue-700":"border-gray-200 hover:bg-gray-50"}`}>{page}</button>
                    );
                  })}
                  <button onClick={()=>setCurrentPage(p=>Math.min(totalPages,p+1))} disabled={currentPage===totalPages} className="px-3 py-1.5 text-xs rounded-lg border border-gray-200 disabled:opacity-40 hover:bg-gray-50 disabled:cursor-not-allowed">Next ›</button>
                  <button onClick={()=>setCurrentPage(totalPages)} disabled={currentPage===totalPages} className="px-2 py-1.5 text-xs rounded-lg border border-gray-200 disabled:opacity-40 hover:bg-gray-50 disabled:cursor-not-allowed">»</button>
                </div>
              </div>
            )}
          </div>
        )}

        {tab==="import" && (
          <div className="space-y-4">
            <div className="bg-blue-50 border border-blue-100 rounded-2xl p-5">
              <div className="flex items-center gap-2 mb-3"><Info size={16} className="text-blue-700"/><h3 className="font-bold text-blue-800 text-sm">CSV Format Guide</h3></div>
              <p className="text-xs text-blue-700 mb-3">Plate numbers must be <span className="font-mono font-bold">3 letters + 3 digits, no spaces</span> (e.g. <span className="font-mono font-bold">ABC123</span>).</p>
              <div className="flex flex-wrap gap-1.5 mb-3">{["plateNumber","applicantName","applicantEmail","applicantAddress","status","classification","assignedOffice"].map(c=><span key={c} className="font-mono text-xs bg-blue-100 text-blue-800 px-2 py-0.5 rounded">{c}</span>)}</div>
              <p className="text-xs text-blue-600 mb-3">Valid statuses: <span className="font-semibold">{VALID_STATUSES.join(", ")}</span></p>
              <button onClick={downloadSample} className="flex items-center gap-2 text-xs bg-blue-700 text-white px-3 py-2 rounded-lg hover:bg-blue-800 font-semibold"><Download size={13}/> Download Sample CSV</button>
            </div>
            <div className="bg-white rounded-2xl border border-gray-100 shadow-sm p-5 space-y-4">
              <h3 className="font-bold text-gray-800">Upload or Paste CSV</h3>
              <div className="border-2 border-dashed border-gray-200 rounded-xl p-6 text-center hover:border-blue-400 transition-colors cursor-pointer" onClick={()=>fileRef.current.click()}>
                <Upload size={24} className="text-gray-400 mx-auto mb-2"/>
                <p className="text-sm font-semibold text-gray-600">Click to upload a .csv file</p>
                <p className="text-xs text-gray-400 mt-1">or paste CSV text below</p>
                <input ref={fileRef} type="file" accept=".csv,text/csv" className="hidden" onChange={handleFile}/>
              </div>
              <textarea value={csvText} onChange={handlePaste} placeholder="plateNumber,vehicleType,...
ABC123,Sedan,..." rows={6} className="w-full border border-gray-200 rounded-xl px-4 py-3 font-mono text-xs text-gray-700 focus:outline-none focus:border-blue-400 resize-none"/>
              {parseResult && (
                <div className="space-y-3">
                  {parseResult.errors.length>0 && <div className="bg-red-50 border border-red-200 rounded-xl p-4 space-y-1"><p className="text-xs font-bold text-red-700 mb-1">Validation Errors</p>{parseResult.errors.map((e,i)=><p key={i} className="text-xs text-red-600 flex gap-2"><XCircle size={12} className="shrink-0 mt-0.5"/>{e}</p>)}</div>}
                  {parseResult.rows.length>0 && (()=>{
                    const seen=new Map(); parseResult.rows.forEach(r=>seen.set(r.plateNumber,r));
                    const dupes=parseResult.rows.length-seen.size;
                    return <div className="bg-green-50 border border-green-200 rounded-xl p-4">
                      <p className="text-xs font-bold text-green-800 mb-1">{seen.size} unique plate(s) ready to import{dupes>0?` (${dupes} duplicate(s) in CSV will be merged)`:""}</p>
                      <div className="space-y-1 max-h-40 overflow-y-auto">{Array.from(seen.values()).map(r=><div key={r.plateNumber} className="flex items-center gap-2 text-xs text-green-700 flex-wrap"><CheckCircle size={12}/><span className="font-mono font-bold">{r.plateNumber}</span><span>— {r.applicantName}</span><StatusBadge status={r.status}/></div>)}</div>
                    </div>;
                  })()}
                  <button disabled={!parseResult.rows.length} onClick={handleImport} className="w-full py-3 bg-blue-700 hover:bg-blue-800 disabled:bg-gray-200 disabled:text-gray-400 text-white font-bold rounded-xl flex items-center justify-center gap-2 text-sm"><PlusCircle size={16}/> Import {new Set(parseResult.rows.map(r=>r.plateNumber)).size} Unique Plate{new Set(parseResult.rows.map(r=>r.plateNumber)).size!==1?"s":""}</button>
                </div>
              )}
            </div>
          </div>
        )}

        {tab==="accounts" && <AccountManager profiles={profiles} setProfiles={setProfiles} currentUser={currentUser}/>}
      </div>
    </div>
  );
}

// ─── Admin Login ──────────────────────────────────────────────────────────────
function AdminLogin({ onLogin }) {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [showPw, setShowPw] = useState(false);
  const [err, setErr] = useState("");
  const [loading, setLoading] = useState(false);

  const handleSubmit = async () => {
    setLoading(true); setErr("");
    const { data, error } = await supabase.auth.signInWithPassword({ email, password });
    if (error) { setErr(error.message); setLoading(false); return; }
    const { data: profile, error: pe } = await supabase
      .from("admin_profiles")
      .select("*")
      .eq("id", data.user.id)
      .maybeSingle();
    if (pe) { setErr("Database error: " + pe.message); await supabase.auth.signOut(); setLoading(false); return; }
    if (!profile) { setErr("Admin profile not found. Please contact the system administrator."); await supabase.auth.signOut(); setLoading(false); return; }
    if (!profile.active) { setErr("This account is inactive. Contact the system administrator."); await supabase.auth.signOut(); setLoading(false); return; }
    onLogin(profile);
    setLoading(false);
  };

  return (
    <div className="min-h-screen bg-gray-50 flex flex-col items-center justify-center px-4">
      <div className="w-full max-w-sm bg-white rounded-2xl shadow-md border border-gray-100 overflow-hidden">
        <div className="bg-blue-900 px-6 py-5 flex items-center gap-3">
          <span className="w-12 h-12 rounded-full bg-white flex items-center justify-center shrink-0 overflow-hidden"><img src={LTO_LOGO} alt="LTO Logo" className="w-12 h-12 object-cover" style={{mixBlendMode:"multiply"}}/></span>
          <div><p className="text-xs text-blue-200 font-semibold">LTO Binangonan</p><h2 className="text-white font-bold">Admin Login</h2></div>
        </div>
        <div className="p-6 space-y-4">
          <div><label className="text-xs font-bold text-gray-500 uppercase tracking-wide block mb-1">Email</label><input type="email" value={email} onChange={e=>{setEmail(e.target.value);setErr("");}} className="w-full border border-gray-200 rounded-xl px-4 py-3 text-sm focus:outline-none focus:border-blue-500" onKeyDown={e=>e.key==="Enter"&&handleSubmit()}/></div>
          <div><label className="text-xs font-bold text-gray-500 uppercase tracking-wide block mb-1">Password</label>
            <div className="relative"><input type={showPw?"text":"password"} value={password} onChange={e=>{setPassword(e.target.value);setErr("");}} className="w-full border border-gray-200 rounded-xl px-4 py-3 pr-10 text-sm focus:outline-none focus:border-blue-500" onKeyDown={e=>e.key==="Enter"&&handleSubmit()}/><button type="button" onClick={()=>setShowPw(s=>!s)} className="absolute right-3 top-1/2 -translate-y-1/2 text-gray-400">{showPw?<EyeOff size={16}/>:<Eye size={16}/>}</button></div>
          </div>
          {err && <p className="text-xs text-red-600 font-semibold flex items-center gap-1"><AlertCircle size={12}/>{err}</p>}
          <button onClick={handleSubmit} disabled={loading} className="w-full py-3 bg-blue-700 hover:bg-blue-800 disabled:bg-gray-300 text-white font-bold rounded-xl flex items-center justify-center gap-2 text-sm">{loading?<><Loader size={15} className="animate-spin"/> Signing in...</>:<><LogIn size={15}/> Sign In</>}</button>
        </div>
      </div>
    </div>
  );
}

