// ─── Root ─────────────────────────────────────────────────────────────────────
export default function App() {
  const [page, setPage] = useState("public");
  const [currentUser, setCurrentUser] = useState(null);
  const [profiles, setProfiles] = useState([]);

  // Restore session on reload
  useEffect(() => {
    supabase.auth.getSession().then(async ({ data }) => {
      if (data.session) {
        const { data: profile } = await supabase.from("admin_profiles").select("*").eq("id", data.session.user.id).single();
        if (profile && profile.active) { setCurrentUser(profile); setPage("admin"); loadProfiles(); }
      }
    });
  }, []);

  const loadProfiles = async () => {
    const { data } = await supabase.from("admin_profiles").select("*").order("created_at");
    if (data) setProfiles(data);
  };

  // Listen for hash changes to allow admin navigation
  useEffect(() => {
    const onHashChange = () => {
      if (window.location.hash === "#admin" && !currentUser) {
        setPage("login");
      } else if (window.location.hash !== "#admin" && !currentUser) {
        setPage("public");
      }
    };
    window.addEventListener("hashchange", onHashChange);
    // Check on mount
    if (window.location.hash === "#admin" && !currentUser) setPage("login");
    return () => window.removeEventListener("hashchange", onHashChange);
  }, [currentUser]);

  const handleLogin = async (profile) => {
    setCurrentUser(profile);
    setPage("admin");
    await loadProfiles();
  };

  const handleLogout = async () => {
    await supabase.auth.signOut();
    setCurrentUser(null);
    setPage("public");
    if (typeof window !== "undefined") window.location.hash = "";
  };

  // Admin accessible only via secret URL hash #admin
  if (typeof window !== "undefined" && window.location.hash === "#admin") {
    if (page === "login" || page === "public") return <AdminLogin onLogin={handleLogin}/>;
    if (page === "admin" && currentUser) return <AdminPanel currentUser={currentUser} profiles={profiles} setProfiles={setProfiles} onLogout={handleLogout}/>;
  }
  if (page === "admin" && currentUser) return <AdminPanel currentUser={currentUser} profiles={profiles} setProfiles={setProfiles} onLogout={handleLogout}/>;
  return <PublicTracker/>;
}
